864	    class RLMCopyTask extends RLMTask {
865	        private final int customMetadataSizeLimit;
866	        private final Logger logger;
867	
868	        // The copied and log-start offset is empty initially for a new RLMCopyTask, and needs to be fetched inside
869	        // the task's run() method.
870	        private volatile Optional<OffsetAndEpoch> copiedOffsetOption = Optional.empty();
871	        private volatile boolean isLogStartOffsetUpdated = false;
872	        private volatile Optional<String> logDirectory = Optional.empty();
873	
874	        public RLMCopyTask(TopicIdPartition topicIdPartition, int customMetadataSizeLimit) {
875	            super(topicIdPartition);
876	            this.customMetadataSizeLimit = customMetadataSizeLimit;
877	            this.logger = getLogContext().logger(RLMCopyTask.class);
878	        }
879	
880	        @Override
881	        protected void execute(UnifiedLog log) throws InterruptedException, RetriableRemoteStorageException {
882	            // In the first run after completing altering logDir within broker, we should make sure the state is reset. (KAFKA-16711)
883	            if (!log.parentDir().equals(logDirectory.orElse(null))) {
884	                copiedOffsetOption = Optional.empty();
885	                isLogStartOffsetUpdated = false;
886	                logDirectory = Optional.of(log.parentDir());
887	            }
888	
889	            copyLogSegmentsToRemote(log);
890	        }
